//! The vault's master key: where it comes from, how it is stored, and what it
//! does and does not protect against.
//!
//! # What the key is
//!
//! One 256-bit key, generated by the operating system's CSPRNG the first time
//! the vault is opened, used to seal every payload and the index with
//! AES-256-GCM. One key and not one per item, because a per-item key would have
//! to be stored somewhere, and that somewhere is the same disk.
//!
//! # What it protects against, honestly
//!
//! The vault directory sits in `%ProgramData%` and is readable by
//! administrators by design — the service runs as `SYSTEM`, the GUI runs as the
//! logged-in user, and both must open the same vault. So the key does **not**
//! defend against a local administrator: such a process can call the same
//! DPAPI unwrap this module calls.
//!
//! What it does defend against is the case that actually happens:
//!
//! * **The vault copied off the machine.** DPAPI's machine scope binds the key
//!   to this installation of Windows. A quarantined sample on a stolen laptop,
//!   in a backup, or in a support bundle is ciphertext elsewhere, and malware
//!   that exfiltrates `%ProgramData%\WenleAV` gains nothing it can execute.
//! * **An unprivileged process reading the vault.** The key file is sealed, and
//!   the vault's own ACLs plus the self-protection rules keep a normal user
//!   process out of the directory in the first place.
//! * **Tampering.** GCM authenticates. A sample cannot be swapped for a
//!   different one, and an index entry cannot be edited to point a "restore" at
//!   a path of the attacker's choosing.
//!
//! Anything stronger would need a key the service holds and the GUI does not,
//! which would in turn need a broker the GUI talks to — a real design, and one
//! this product does not have.

use std::path::Path;

use zeroize::Zeroize;

use crate::error::{QuarantineError, Result};
use crate::fsutil;
use crate::random;

/// Length of the master key in bytes.
pub const KEY_BYTES: usize = 32;

/// Magic bytes at the head of the key file, so that a file that is not a key
/// file at all is rejected as such rather than parsed into nonsense.
const MAGIC: &[u8; 4] = b"WAVK";

/// Format version of the key file.
const FORMAT_VERSION: u8 = 1;

/// How the key bytes in the file are protected.
const PROTECTION_DPAPI: u8 = 1;
/// Stored in the clear. Only produced on platforms without DPAPI, and by
/// tests that need a vault they can reopen from a second process.
const PROTECTION_PLAIN: u8 = 0;

/// The 256-bit key every payload and the index are sealed with.
///
/// Deliberately not `Clone` and not `Copy`: the fewer copies of this value
/// exist, the fewer places have to be audited for a leak, and no caller in this
/// crate ever needs a second one.
pub struct MasterKey([u8; KEY_BYTES]);

impl MasterKey {
    /// A fresh key from the operating system's CSPRNG.
    pub fn generate() -> Self {
        let mut bytes = [0u8; KEY_BYTES];
        random::fill(&mut bytes);
        Self(bytes)
    }

    /// Wrap bytes that came from somewhere else.
    pub const fn from_bytes(bytes: [u8; KEY_BYTES]) -> Self {
        Self(bytes)
    }

    /// The raw key material, for the cipher.
    pub const fn as_bytes(&self) -> &[u8; KEY_BYTES] {
        &self.0
    }

    /// Load the key at `path`, creating and storing a new one if it is not
    /// there.
    ///
    /// This is the only way a key comes into existence, which is what keeps the
    /// "one vault, one key" invariant from depending on the callers.
    pub fn load_or_create(path: &Path) -> Result<Self> {
        match Self::load(path)? {
            Some(key) => Ok(key),
            None => {
                let key = Self::generate();
                let encoded = key.encode()?;
                // `write_atomic` first and the key in memory second: if the
                // write fails there is no key, and a vault sealed with a key
                // that was never stored is a vault nobody can ever open.
                fsutil::write_atomic(path, &encoded)?;
                log::info!("created a new quarantine master key at {}", path.display());
                Ok(key)
            }
        }
    }

    /// Read the key at `path`, and make nothing.
    ///
    /// The read-only half, split out so that a caller which must not write to
    /// the vault — the window, which shows the same vault the service owns —
    /// has no way to make a key by accident. The absence of the file is
    /// `Ok(None)` rather than an error, because only the caller knows whether
    /// that is a vault that has never been used or one that is missing its key.
    pub fn load(path: &Path) -> Result<Option<Self>> {
        match fsutil::read_optional(path)? {
            Some(stored) => Self::decode(&stored).map(Some),
            None => Ok(None),
        }
    }

    /// Serialize the key into the on-disk form.
    fn encode(&self) -> Result<Vec<u8>> {
        let wrapped = match wrap(&self.0) {
            Ok(wrapped) => (PROTECTION_DPAPI, wrapped),
            Err(e) => {
                // Not fatal. A machine where DPAPI is unavailable still gets an
                // encrypted vault; it loses only the guarantee that the key
                // cannot be unwrapped on another machine.
                log::warn!(
                    "the quarantine key could not be protected by the operating system ({e}); \
                     it is being stored with filesystem permissions alone"
                );
                (PROTECTION_PLAIN, self.0.to_vec())
            }
        };

        let mut out = Vec::with_capacity(5 + wrapped.1.len());
        out.extend_from_slice(MAGIC);
        out.push(FORMAT_VERSION);
        out.push(wrapped.0);
        out.extend_from_slice(&wrapped.1);
        Ok(out)
    }

    /// Parse the on-disk form back into a key.
    fn decode(stored: &[u8]) -> Result<Self> {
        if stored.len() < 5 || &stored[..4] != MAGIC {
            return Err(QuarantineError::Key(format!(
                "the key file is {} bytes and does not start with the expected header",
                stored.len()
            )));
        }
        let version = stored[4];
        if version != FORMAT_VERSION {
            return Err(QuarantineError::Key(format!(
                "the key file is format version {version}, and this build writes version \
                 {FORMAT_VERSION}"
            )));
        }
        // The protection byte is the sixth byte, which is why the header check
        // above insists on at least five before reading it.
        let Some((&protection, payload)) = stored.get(5).map(|p| (p, &stored[6..])) else {
            return Err(QuarantineError::Key(
                "the key file has a header but no protection byte".into(),
            ));
        };

        let raw = match protection {
            PROTECTION_DPAPI => unwrap(payload)?,
            PROTECTION_PLAIN => {
                log::warn!(
                    "the quarantine key is not protected by the operating system; the vault is \
                     still encrypted, but the key travels with it"
                );
                payload.to_vec()
            }
            other => {
                return Err(QuarantineError::Key(format!(
                    "the key file names protection scheme {other}, which this build does not know"
                )))
            }
        };

        let bytes: [u8; KEY_BYTES] = raw.as_slice().try_into().map_err(|_| {
            QuarantineError::Key(format!(
                "the key is {} bytes after unwrapping, not {KEY_BYTES}",
                raw.len()
            ))
        })?;
        Ok(Self(bytes))
    }
}

impl Drop for MasterKey {
    fn drop(&mut self) {
        self.0.zeroize();
    }
}

impl std::fmt::Debug for MasterKey {
    /// Never prints the key. A key that reaches a log file has to be rotated,
    /// and rotating it means every quarantined sample becomes unreadable.
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("MasterKey(<redacted>)")
    }
}

/// Hand the key to the operating system and get back a blob only this machine
/// can turn back into a key.
#[cfg(windows)]
fn wrap(key: &[u8; KEY_BYTES]) -> Result<Vec<u8>> {
    dpapi(key, true)
}

/// The inverse of [`wrap`].
#[cfg(windows)]
fn unwrap(wrapped: &[u8]) -> Result<Vec<u8>> {
    dpapi(wrapped, false)
}

/// Platforms without DPAPI keep the key as it is.
#[cfg(not(windows))]
fn wrap(key: &[u8; KEY_BYTES]) -> Result<Vec<u8>> {
    Err(QuarantineError::Key(
        "this platform has no equivalent of DPAPI".into(),
    ))
}

/// Platforms without DPAPI keep the key as it is.
#[cfg(not(windows))]
fn unwrap(wrapped: &[u8]) -> Result<Vec<u8>> {
    Ok(wrapped.to_vec())
}

/// `CryptProtectData` / `CryptUnprotectData` with machine scope.
///
/// Machine scope rather than user scope because the service and the GUI are
/// different accounts and both must reach the vault. It is the weaker of the
/// two scopes against a local administrator, which is stated plainly in this
/// module's documentation rather than left for a reader to discover.
#[cfg(windows)]
fn dpapi(input: &[u8], protect: bool) -> Result<Vec<u8>> {
    use windows::Win32::Foundation::{LocalFree, HLOCAL};
    use windows::Win32::Security::Cryptography::{
        CryptProtectData, CryptUnprotectData, CRYPT_INTEGER_BLOB,
    };

    /// `CRYPTPROTECT_LOCAL_MACHINE`. Written as a literal because the generated
    /// binding exposes it as a typed flag constant whose conversion would be
    /// noise at the call site.
    const LOCAL_MACHINE: u32 = 0x4;

    let input_blob = CRYPT_INTEGER_BLOB {
        cbData: input.len() as u32,
        pbData: input.as_ptr() as *mut u8,
    };
    let mut output_blob = CRYPT_INTEGER_BLOB::default();

    // SAFETY: both blobs point at live memory for the duration of the call.
    // `input_blob` describes a slice the caller owns; `output_blob` is a
    // zeroed out-parameter that the API fills with a `LocalAlloc` allocation on
    // success, which is copied out and freed immediately below. The optional
    // arguments — entropy, reserved pointer, prompt structure — are null,
    // which the API documents as "none".
    let outcome = unsafe {
        if protect {
            CryptProtectData(
                &input_blob,
                windows::core::PCWSTR::null(),
                None,
                None,
                None,
                LOCAL_MACHINE,
                &mut output_blob,
            )
        } else {
            CryptUnprotectData(
                &input_blob,
                None,
                None,
                None,
                None,
                LOCAL_MACHINE,
                &mut output_blob,
            )
        }
    };

    if let Err(e) = outcome {
        return Err(QuarantineError::Key(format!(
            "the operating system refused to {} the key: {e}",
            if protect { "protect" } else { "unprotect" }
        )));
    }

    // SAFETY: on success the API guarantees `pbData` points at `cbData` bytes
    // of readable memory allocated by `LocalAlloc`.
    let bytes = unsafe {
        std::slice::from_raw_parts(output_blob.pbData, output_blob.cbData as usize).to_vec()
    };
    // SAFETY: the pointer came from `LocalAlloc` inside the API and has not
    // been freed; `LocalFree` on it is the documented way to release it. The
    // return value is null on success and is not otherwise useful.
    unsafe {
        let _ = LocalFree(Some(HLOCAL(output_blob.pbData as *mut std::ffi::c_void)));
    }

    Ok(bytes)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn dir() -> tempfile::TempDir {
        tempfile::tempdir().expect("a temporary directory")
    }

    #[test]
    fn a_generated_key_outlives_a_reload() {
        let d = dir();
        let path = d.path().join("master.key");
        let first = MasterKey::load_or_create(&path).unwrap();
        let expected = *first.as_bytes();
        drop(first);

        let second = MasterKey::load_or_create(&path).unwrap();
        assert_eq!(second.as_bytes(), &expected);
    }

    #[test]
    fn creating_the_key_leaves_a_file_with_the_expected_header() {
        let d = dir();
        let path = d.path().join("master.key");
        let _key = MasterKey::load_or_create(&path).unwrap();
        let stored = std::fs::read(&path).unwrap();
        assert_eq!(&stored[..4], MAGIC);
        assert_eq!(stored[4], FORMAT_VERSION);
        // The key itself must not appear in the file when it is protected.
        if stored[5] == PROTECTION_DPAPI {
            assert!(!stored.windows(KEY_BYTES).any(|w| w == _key.as_bytes()));
        }
    }

    #[test]
    fn the_wrapped_key_round_trips_through_the_encoders() {
        let key = MasterKey::generate();
        let encoded = key.encode().unwrap();
        let decoded = MasterKey::decode(&encoded).unwrap();
        assert_eq!(key.as_bytes(), decoded.as_bytes());
    }

    #[test]
    fn a_file_that_is_not_a_key_file_is_refused_by_name() {
        let err = MasterKey::decode(b"NOPE\x01\x00rest").unwrap_err();
        assert!(matches!(err, QuarantineError::Key(_)), "{err:?}");
        assert!(err.to_string().contains("header"), "{err}");
    }

    #[test]
    fn a_truncated_key_file_is_refused_rather_than_panicking() {
        for len in 0..=6usize {
            let mut stored = MAGIC.to_vec();
            stored.push(FORMAT_VERSION);
            stored.push(PROTECTION_PLAIN);
            stored.truncate(len);
            let err = MasterKey::decode(&stored).unwrap_err();
            assert!(matches!(err, QuarantineError::Key(_)), "len {len}: {err:?}");
        }
    }

    #[test]
    fn a_future_format_version_is_refused_by_name() {
        let mut stored = MAGIC.to_vec();
        stored.push(FORMAT_VERSION + 1);
        stored.push(PROTECTION_PLAIN);
        stored.extend_from_slice(&[0u8; KEY_BYTES]);
        let err = MasterKey::decode(&stored).unwrap_err().to_string();
        assert!(err.contains("format version"), "{err}");
    }

    #[test]
    fn an_unknown_protection_scheme_is_refused_by_name() {
        let mut stored = MAGIC.to_vec();
        stored.push(FORMAT_VERSION);
        stored.push(0x7f);
        stored.extend_from_slice(&[0u8; KEY_BYTES]);
        let err = MasterKey::decode(&stored).unwrap_err().to_string();
        assert!(err.contains("protection scheme"), "{err}");
    }

    #[test]
    fn a_plain_key_of_the_wrong_length_is_refused() {
        let mut stored = MAGIC.to_vec();
        stored.push(FORMAT_VERSION);
        stored.push(PROTECTION_PLAIN);
        stored.extend_from_slice(&[0u8; 17]);
        let err = MasterKey::decode(&stored).unwrap_err().to_string();
        assert!(err.contains("not 32"), "{err}");
    }

    #[test]
    fn the_debug_form_never_shows_the_key() {
        let key = MasterKey::from_bytes([0xAB; KEY_BYTES]);
        let shown = format!("{key:?}");
        assert_eq!(shown, "MasterKey(<redacted>)");
        assert!(!shown.contains("171"), "{shown}");
    }

    #[test]
    fn two_generated_keys_differ() {
        assert_ne!(
            MasterKey::generate().as_bytes(),
            MasterKey::generate().as_bytes()
        );
    }

    #[cfg(windows)]
    #[test]
    fn dpapi_round_trips_a_key_on_this_machine() {
        let key = MasterKey::generate();
        let wrapped = wrap(key.as_bytes()).expect("DPAPI must be available on Windows");
        assert_ne!(wrapped.as_slice(), key.as_bytes());
        assert_eq!(unwrap(&wrapped).unwrap(), key.as_bytes().to_vec());
    }

    #[cfg(windows)]
    #[test]
    fn a_corrupted_dpapi_blob_is_refused_rather_than_returning_nonsense() {
        let key = MasterKey::generate();
        let mut wrapped = wrap(key.as_bytes()).unwrap();
        let last = wrapped.len() - 1;
        wrapped[last] ^= 0xff;
        assert!(unwrap(&wrapped).is_err());
    }
}
